'use strict';
const $=id=>document.getElementById(id);let admin=false;const players=new Map();
function message(text){$('status').textContent=text}
async function api(url,options={}){const response=await fetch(url,{...options,cache:'no-store'});const result=await response.json();if(!response.ok){if(response.status===401&&admin){admin=false;render().catch(()=>{});}throw new Error(result.error||'Operazione non riuscita.')}return result}
const staticPreview=location.hostname.endsWith('.github.io');
async function init(){if(staticPreview){$('access').disabled=true;$('access').textContent='Anteprima';message('Anteprima grafica: caricamento, accesso amministratore e raccolta condivisa saranno disponibili quando sarà collegato il server.');return}try{admin=(await api('/api/session')).admin;await render()}catch{message('Connessione al server non disponibile. Riprova quando sei online.')}}
function stopAll(){for(const audio of players.values()){audio.pause();audio.currentTime=0}document.querySelectorAll('.play').forEach(b=>{b.textContent='▶ Play';b.classList.remove('playing')})}
async function render(){stopAll();players.clear();$('add').hidden=!admin;$('access').textContent=admin?'Esci da amministratore':'Accesso amministratore';const sounds=await api('/api/sounds');$('sounds').replaceChildren();$('empty').hidden=sounds.length>0;$('count').textContent=sounds.length;for(const sound of sounds){const card=document.createElement('article');card.className='card';const play=document.createElement('button');play.className='play';play.textContent='▶ Play';const label=document.createElement('input');label.className='label';label.value=sound.label;label.maxLength=80;label.readOnly=!admin;label.setAttribute('aria-label','Etichetta del suono');play.setAttribute('aria-label','Riproduci '+sound.label);const audio=new Audio(sound.url);audio.preload='none';players.set(sound.id,audio);const reset=()=>{play.textContent='▶ Play';play.classList.remove('playing')};audio.onended=reset;audio.onerror=()=>{reset();message('Questo audio non è riproducibile nel browser. Prova un file MP3 o WAV.')};play.onclick=async()=>{if(!audio.paused){audio.pause();reset();return}stopAll();try{await audio.play();play.textContent='Ⅱ Pausa';play.classList.add('playing')}catch{reset();message('Riproduzione non riuscita. Verifica il formato del file audio.')}};label.onchange=async()=>{sound.label=label.value.trim()||sound.name;label.value=sound.label;try{await api('/api/sounds/'+sound.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({label:sound.label})});play.setAttribute('aria-label','Riproduci '+sound.label)}catch{message('Non è stato possibile salvare l’etichetta.')}};const meta=document.createElement('div');meta.className='meta';meta.textContent=sound.name;const remove=document.createElement('button');remove.className='remove';remove.hidden=!admin;remove.textContent='Rimuovi';remove.setAttribute('aria-label','Rimuovi '+sound.label);remove.onclick=async()=>{try{await api('/api/sounds/'+sound.id,{method:'DELETE'});await render()}catch{message('Rimozione non riuscita.')}};card.append(play,label,meta,remove);$('sounds').append(card)}}
$('add').onclick=()=>$('files').click();$('stop').onclick=stopAll;
$('files').onchange=async event=>{if(!admin)return;const files=Array.from(event.target.files);$('add').disabled=true;let added=0;try{for(const file of files){if(file.size>20*1024*1024)throw new Error('Ogni file può pesare al massimo 20 MB.');await api('/api/sounds',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file});added++}message(added+' suoni aggiunti. Tocca le etichette per modificarle.')}catch(error){message(error.message)}finally{event.target.value='';$('add').disabled=false;await render().catch(()=>message('Impossibile aggiornare la raccolta.'))}};
$('access').onclick=async()=>{if(admin){try{await api('/api/logout',{method:'POST'});admin=false;await render();message('Modalità ascolto.')}catch(error){message(error.message)}return}$('loginError').textContent='';$('code').value='';$('login').showModal();$('code').focus()};
$('cancel').onclick=()=>$('login').close();
$('loginForm').onsubmit=async event=>{event.preventDefault();const submit=event.submitter;submit.disabled=true;try{await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:$('code').value})});admin=true;$('code').value='';$('login').close();await render();message('Accesso amministratore attivo. Puoi aggiungere suoni e modificare le etichette.')}catch(error){$('loginError').textContent=error.message}finally{submit.disabled=false}};
window.addEventListener('focus',()=>{if(!$('login').open)init()});init();
let installPrompt;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('install').hidden=false});$('install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();installPrompt=null;$('install').hidden=true};
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>message('Modalità offline non disponibile. Apri l’app tramite HTTPS.'));
